<?php
require_once __DIR__.'/includes/appointment_helpers.php';require_patient();
$doctorId=filter_var($_GET['doctor_id']??$_POST['doctor_id']??null,FILTER_VALIDATE_INT);$date=(string)($_GET['date']??$_POST['appointment_date']??'');$symptoms='';$errors=[];
if(!$doctorId||!doctor_is_approved($pdo,(int)$doctorId)){http_response_code(404);exit('Doctor not found or not approved.');}
$s=$pdo->prepare('SELECT u.full_name,dp.specialty,dp.qualification,dp.consultation_fee FROM users u JOIN doctor_profiles dp ON dp.user_id=u.id WHERE u.id=?');$s->execute([$doctorId]);$doctor=$s->fetch();
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$date=trim((string)($_POST['appointment_date']??''));$time=trim((string)($_POST['appointment_time']??''));$symptoms=trim((string)($_POST['symptoms']??''));
 if(!is_valid_future_date($date))$errors[]='Choose today or a future date.';
 if(!preg_match('/^(?:[01]\d|2[0-3]):[0-5]\d$/',$time))$errors[]='Choose a valid time.';
 if($symptoms===''||mb_strlen($symptoms)>3000)$errors[]='Enter the reason for consultation (maximum 3,000 characters).';
 if(!$errors){try{$pdo->beginTransaction();$lock=$pdo->prepare('SELECT id FROM users WHERE id=? AND role="doctor" FOR UPDATE');$lock->execute([$doctorId]);if(!$lock->fetch()||!doctor_is_approved($pdo,$doctorId))throw new RuntimeException('Doctor is no longer available.');
  $timeDb=$time.':00';if(!time_is_in_doctor_availability($pdo,$doctorId,$date,$timeDb))throw new RuntimeException('This time is outside the doctor’s availability.');
  $c=$pdo->prepare('SELECT id FROM appointments WHERE doctor_id=? AND appointment_date=? AND appointment_time=? AND status IN ("pending","confirmed","rescheduled") LIMIT 1');$c->execute([$doctorId,$date,$timeDb]);if($c->fetch())throw new RuntimeException('This slot has just been booked. Choose another time.');
  $i=$pdo->prepare('INSERT INTO appointments(patient_id,doctor_id,appointment_date,appointment_time,symptoms,status) VALUES(?,?,?,?,?,"pending")');$i->execute([$_SESSION['user_id'],$doctorId,$date,$timeDb,$symptoms]);$pdo->commit();flash('Appointment request submitted and is awaiting the doctor’s response.');header('Location: my_appointments.php');exit;
 }catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$errors[]=$e instanceof RuntimeException?$e->getMessage():'Could not submit appointment. Please try again.';if(!$e instanceof RuntimeException)error_log($e->getMessage());}}}
$slots=$date&&is_valid_future_date($date)?get_doctor_slots($pdo,$doctorId,$date):[];
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Book appointment | MediConnect</title><link rel="stylesheet" href="assets/css/auth.css"></head><body><main class="dashboard-shell"><header class="dashboard-header"><a class="brand" href="dashboard.php">✚ MediConnect</a><a href="doctor_directory.php">Find doctors</a></header><section class="welcome-panel"><p class="eyebrow">APPOINTMENT REQUEST</p><h1>Book with <?=e($doctor['full_name'])?></h1><p class="muted"><?=e($doctor['specialty'])?> · <?=e($doctor['qualification'])?></p></section><?php if($errors):?><div class="alert error"><?php foreach($errors as $x):?><p><?=e($x)?></p><?php endforeach;?></div><?php endif;?>
<section class="profile-panel"><form method="get"><input type="hidden" name="doctor_id" value="<?=(int)$doctorId?>"><label>Appointment date<input type="date" name="date" min="<?=e((new DateTime('today'))->format('Y-m-d'))?>" value="<?=e($date)?>" required></label><button class="secondary-button">Check times</button></form>
<?php if($date&&is_valid_future_date($date)):?><form method="post"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="doctor_id" value="<?=(int)$doctorId?>"><input type="hidden" name="appointment_date" value="<?=e($date)?>"><label>Available 30-minute start time<?php if($slots):?><select name="appointment_time" required><?php foreach($slots as $slot):?><option value="<?=e(substr($slot,0,5))?>"><?=e(date('g:i A',strtotime($slot)))?></option><?php endforeach;?></select><?php else:?><p>No available slots for this date. Try another date.</p><?php endif;?></label><label>Reason for consultation / symptoms<textarea name="symptoms" rows="5" maxlength="3000" required><?=e($symptoms)?></textarea></label><?php if($slots):?><button class="primary-button">Submit request</button><?php endif;?></form><?php endif;?></section><p class="fine-print">For emergencies, seek urgent care at the nearest hospital. This application is not an emergency service.</p></main></body></html>
